using System;using System.Runtime.InteropServices;
public static class MclaLifecycleNative{delegate bool E(IntPtr h,IntPtr p);[StructLayout(LayoutKind.Sequential)]struct R{public int l,t,r,b;}[StructLayout(LayoutKind.Sequential)]struct P{public int x,y;}[DllImport("user32.dll")]static extern bool EnumWindows(E c,IntPtr p);[DllImport("user32.dll")]static extern uint GetWindowThreadProcessId(IntPtr h,out uint p);[DllImport("user32.dll")]static extern bool IsWindowVisible(IntPtr h);[DllImport("user32.dll")]static extern bool IsIconic(IntPtr h);[DllImport("user32.dll")]static extern bool ShowWindow(IntPtr h,int n);[DllImport("user32.dll")]static extern bool SetForegroundWindow(IntPtr h);[DllImport("user32.dll")]static extern bool PostMessage(IntPtr h,uint m,IntPtr w,IntPtr l);[DllImport("user32.dll")]static extern bool GetClientRect(IntPtr h,out R r);[DllImport("user32.dll")]static extern bool ClientToScreen(IntPtr h,ref P p);public static IntPtr Handle(int pid){IntPtr found=IntPtr.Zero;EnumWindows(delegate(IntPtr h,IntPtr x){uint p;GetWindowThreadProcessId(h,out p);if(p==(uint)pid&&IsWindowVisible(h)&&found==IntPtr.Zero)found=h;return true;},IntPtr.Zero);return found;}public static bool Minimize(IntPtr h){ShowWindow(h,6);return IsIconic(h);}public static bool Restore(IntPtr h){ShowWindow(h,9);SetForegroundWindow(h);return !IsIconic(h);}public static bool Iconic(IntPtr h){return IsIconic(h);}public static bool Close(IntPtr h){return PostMessage(h,0x10,IntPtr.Zero,IntPtr.Zero);}public static int[] Client(IntPtr h){R r;if(!GetClientRect(h,out r))throw new Exception("GetClientRect failed");P p=new P();if(!ClientToScreen(h,ref p))throw new Exception("ClientToScreen failed");return new[]{p.x,p.y,r.r-r.l,r.b-r.t};}}
'@}
function Read-Shared([string]$path){$stream=[IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::ReadWrite-bor[IO.FileShare]::Delete);try{$reader=[IO.StreamReader]::new($stream,[Text.Encoding]::UTF8,$true);try{$reader.ReadToEnd()}finally{$reader.Dispose()}}finally{$stream.Dispose()}}
function Wait-FileText([Diagnostics.Process]$p,[string]$log,[string]$needle,[int]$seconds){$sw=[Diagnostics.Stopwatch]::StartNew();while($sw.Elapsed.TotalSeconds-lt$seconds){if($p.HasExited){throw "Process exited while waiting for '$needle'."};if(Test-Path $log){try{if((Read-Shared $log).Contains($needle)){return}}catch [System.IO.IOException]{}};Start-Sleep -Milliseconds 100};throw "Timed out waiting for '$needle'."}
