ons.Generic.HashSet[int]';$luma=New-Object 'System.Collections.Generic.List[int]';for($y=0;$y-lt$image.Height;$y+=8){for($x=0;$x-lt$image.Width;$x+=8){$c=$image.GetPixel($x,$y);$null=$bins.Add((($c.R-shr3)-shl10)-bor(($c.G-shr3)-shl5)-bor($c.B-shr3));$luma.Add([int](($c.R*54+$c.G*183+$c.B*19)-shr8))}};$a=$luma.ToArray();[Array]::Sort($a);$range=$a[[int]($a.Length*.95)]-$a[[int]($a.Length*.05)]}finally{$image.Dispose()};if($bins.Count-lt128-or$range-lt40){throw 'Restored capture is not a valid nontrivial frame.'};if(-not[MclaLifecycleNative]::Minimize($hwnd)){Start-Sleep -Milliseconds 500};$second=[MclaLifecycleNative]::Iconic($hwnd);$close=[MclaLifecycleNative]::Close($hwnd);$exit=[Diagnostics.Stopwatch]::StartNew();$done=$process.WaitForExit(10000);$exit.Stop();if(-not$done-or$process.ExitCode-ne0){throw 'Close-while-minimized did not exit 0.'}}catch{$failure=$_;if($process-and-not$process.HasExited){$forced=$true;Stop-Process -Id $process.Id -Force -ErrorAction SilentlyContinue;$null=$process.WaitForExit(5000)};if($forced){throw "M6-010 failure required force cleanup. $($failure.Exception.Message) Private run: '$root'."};throw}
